// =================================================================================
//   MATH & PHYSICS HELPERS
// =================================================================================

  // Calculates delta phi ensuring range [0, pi]
  double RelativePhi(double phi_1, double phi_2) {
    static const double PI = std::acos(-1); // Calculated once
    double d_phi = std::abs(phi_1 - phi_2);
    if (d_phi > PI) d_phi = 2 * PI - d_phi;
    return d_phi;
 }

  // Calculates Delta R between two sets of coordinates
  double getDeltaR(double eta1, double phi1, double eta2, double phi2) {
    double dEta = eta1 - eta2;
    double dPhi = RelativePhi(phi1, phi2);
    return std::sqrt(dEta * dEta + dPhi * dPhi);
  }

  // Simple structure for MinBias Jets
  struct MinBiasJetInfo {
    float pt;
    float eta;
    float phi;
  };

// =================================================================================
//   FILE LOADING HELPERS
// =================================================================================

  // Helper to load a weight histogram from a file safely
  TH1D* loadWeightHist(const std::string& filepath, const std::string& histname) {
    TFile* f = TFile::Open(filepath.c_str(), "READ");
    if (!f || f->IsZombie()) {
      std::cerr << "Error: Cannot open file " << filepath << std::endl;
      return nullptr;
    }
    TH1D* h = (TH1D*)f->Get(histname.c_str());
    if (!h) {
      std::cerr << "Error: Cannot find histogram " << histname << " in " << filepath << std::endl;
      f->Close();
      return nullptr;
    }
    h->SetDirectory(0); // Detach from file
    f->Close();
    return h;
  }

