 /**
  * @brief Mimics the CentralityBinProducer logic to find the hiBin from hiHF.
  * @param hiHF The transverse energy sum in the HF calorimeter.
  * @param table The centrality table (must be sorted in ascending HF order: 0.0 -> High)
  * @return int The corresponding centrality bin (0-199).
  */
  int getHiBin(float hiHF, const std::vector<double>& table) {
    // The table has N bins (200).
    int nbins = table.size();
    // Iterate from 0 to 199
    for (unsigned int i = 0; i < nbins; ++i) {
      // Logic: Check thresholds from Highest (Central) to Lowest (Peripheral).
      // For a size 200 table:
      // i=0   checks table[199] (e.g., 5305.56). If hiHF >= 5305, returns 0.
      // i=199 checks table[0]   (e.g., 0.0).     If hiHF >= 0,    returns 199.
      if (hiHF >= table[nbins - 1 - i]) {
        return i;
      }
    }
    // Fallback: If hiHF is lower than table[0] (e.g. negative noise), assign to the most peripheral bin.
    return nbins - 1;
  }

